export type KanbanCardBase = { id: string };

export type KanbanColumnBase<T extends KanbanCardBase = KanbanCardBase> = {
  id: string;
  title: string;
  cards: T[];
};

export type DragType = "card" | "column";

export interface CardDragData<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
> {
  type: "card";
  card: TCard;
  column: TColumn;
  columnId: string;
}

export interface ColumnDragData<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
> {
  type: "column";
  column: TColumn;
}

export interface CardRenderMeta {
  /** True on the original slot while a ghost is being dragged */
  isDragging: boolean;
  /** True on the ghost inside DragOverlay */
  isOverlay: boolean;
}

export interface ColumnRenderMeta {
  cardCount: number;
  /** True while a foreign card is dragged over this column */
  isOver: boolean;
}

export interface KanbanContextValue<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
> {
  /** Current (potentially virtual) column state — reflects in-drag positions */
  columns: TColumn[];
  activeId: string | null;
  activeType: DragType | null;
  /** The card currently being dragged (for DragOverlay) */
  activeCard: TCard | null;
  /** The column of the active card at drag-start (for DragOverlay) */
  activeCardColumn: TColumn | null;
  /** The column being dragged (for DragOverlay) */
  activeColumnData: TColumn | null;

  renderCard: (
    card: TCard,
    column: TColumn,
    meta: CardRenderMeta,
  ) => React.ReactNode;
  renderColumnHeader?: (
    column: TColumn,
    meta: ColumnRenderMeta,
  ) => React.ReactNode;
  renderColumnFooter?: (
    column: TColumn,
    meta: ColumnRenderMeta,
  ) => React.ReactNode;
  renderEmptyColumn?: (column: TColumn) => React.ReactNode;
}

import { arrayMove } from "@dnd-kit/sortable";
import type { KanbanCardBase, KanbanColumnBase } from "./types";

export function findCard<T extends KanbanCardBase>(
  columns: KanbanColumnBase<T>[],
  cardId: string,
): T | null {
  for (const col of columns) {
    const card = col.cards.find((c) => c.id === cardId);
    if (card) return card;
  }
  return null;
}

export function findCardColumn<T extends KanbanCardBase>(
  columns: KanbanColumnBase<T>[],
  cardId: string,
): KanbanColumnBase<T> | null {
  return columns.find((col) => col.cards.some((c) => c.id === cardId)) ?? null;
}

export function findColumn<T extends KanbanCardBase>(
  columns: KanbanColumnBase<T>[],
  columnId: string,
): KanbanColumnBase<T> | null {
  return columns.find((c) => c.id === columnId) ?? null;
}

/**
 * Reorder a card within the same column.
 */
export function moveCardWithinColumn<
  T extends KanbanCardBase,
  C extends KanbanColumnBase<T>,
>(columns: C[], columnId: string, fromIndex: number, toIndex: number): C[] {
  return columns.map((col) => {
    if (col.id !== columnId) return col;
    return { ...col, cards: arrayMove(col.cards, fromIndex, toIndex) };
  });
}

/**
 * Move a card from one column to another, inserting at toIndex.
 * toIndex defaults to end of target column if not specified.
 */
export function moveCardBetweenColumns<
  T extends KanbanCardBase,
  C extends KanbanColumnBase<T>,
>(
  columns: C[],
  cardId: string,
  fromColumnId: string,
  toColumnId: string,
  toIndex?: number,
): C[] {
  const card = findCard(columns, cardId);
  if (!card) return columns;

  return columns.map((col) => {
    if (col.id === fromColumnId) {
      return { ...col, cards: col.cards.filter((c) => c.id !== cardId) };
    }
    if (col.id === toColumnId) {
      const next = [...col.cards];
      const insertAt =
        toIndex !== undefined && toIndex >= 0 ? toIndex : next.length;
      next.splice(Math.min(insertAt, next.length), 0, card);
      return { ...col, cards: next };
    }
    return col;
  });
}

/**
 * Reorder columns by index.
 */
export function reorderColumns<C extends KanbanColumnBase<KanbanCardBase>>(
  columns: C[],
  fromIndex: number,
  toIndex: number,
): C[] {
  return arrayMove(columns, fromIndex, toIndex);
}

import * as React from "react";
import {
  PointerSensor,
  KeyboardSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragOverEvent,
  type DragEndEvent,
  MeasuringStrategy,
  DndContext,
  closestCorners,
} from "@dnd-kit/core";
import { sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import {
  findCard,
  findCardColumn,
  moveCardWithinColumn,
  moveCardBetweenColumns,
  reorderColumns,
} from "./kanban-engine";
import type {
  KanbanCardBase,
  KanbanColumnBase,
  KanbanContextValue,
  CardRenderMeta,
  ColumnRenderMeta,
  DragType,
} from "./types";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const KanbanCtx = React.createContext<KanbanContextValue<
  any,
  any
> | null>(null);

export function useKanban<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard> = KanbanColumnBase<TCard>,
>(): KanbanContextValue<TCard, TColumn> {
  const ctx = React.useContext(KanbanCtx);
  if (!ctx) throw new Error("useKanban must be used inside KanbanRoot");
  return ctx as KanbanContextValue<TCard, TColumn>;
}

export interface KanbanProviderProps<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard> = KanbanColumnBase<TCard>,
> {
  columns: TColumn[];
  /**
   * Called once per drag-end with the full updated columns array.
   * Use this to persist state.
   */
  onColumnsChange?: (columns: TColumn[]) => void;
  /**
   * Granular callback — called when a card moves column or position.
   * Card's new index is its position in the destination column.
   */
  onCardMove?: (
    card: TCard,
    fromColumnId: string,
    toColumnId: string,
    toIndex: number,
  ) => void;
  /** Called when columns are reordered. */
  onColumnReorder?: (fromIndex: number, toIndex: number) => void;

  /**
   * Render the card content. Receives the card, its column, and drag meta.
   * Used in the column list AND in the DragOverlay ghost.
   */
  renderCard: (
    card: TCard,
    column: TColumn,
    meta: CardRenderMeta,
  ) => React.ReactNode;
  /**
   * Render the column header. Also acts as the drag handle for column reordering.
   * Default: a simple title row.
   */
  renderColumnHeader?: (
    column: TColumn,
    meta: ColumnRenderMeta,
  ) => React.ReactNode;
  /**
   * Render the column footer — typically an "Add card" button.
   * Rendered below the card list.
   */
  renderColumnFooter?: (
    column: TColumn,
    meta: ColumnRenderMeta,
  ) => React.ReactNode;
  /**
   * Render content when a column has no cards.
   * Default: a dashed empty-drop zone.
   */
  renderEmptyColumn?: (column: TColumn) => React.ReactNode;
  children: React.ReactNode;
}

export function KanbanProvider<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard> = KanbanColumnBase<TCard>,
>({
  columns: columnsProp,
  onColumnsChange,
  onCardMove,
  onColumnReorder,
  renderCard,
  renderColumnHeader,
  renderColumnFooter,
  renderEmptyColumn,
  children,
}: KanbanProviderProps<TCard, TColumn>) {
  const [dragColumns, setDragColumns] = React.useState<TColumn[]>(columnsProp);
  const [activeId, setActiveId] = React.useState<string | null>(null);
  const [activeType, setActiveType] = React.useState<DragType | null>(null);

  // Refs for rollback and cross-event tracking
  const snapshotRef = React.useRef<TColumn[]>(columnsProp);
  const activeCardColumnRef = React.useRef<string | null>(null);

  // Sync drag columns when external prop changes (only when not dragging)
  React.useEffect(() => {
    if (!activeId) setDragColumns(columnsProp);
  }, [columnsProp, activeId]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  function onDragStart({ active }: DragStartEvent) {
    const data = active.data.current;
    setActiveId(active.id as string);
    setActiveType(data?.type ?? "card");
    if (data?.type === "card") {
      activeCardColumnRef.current = data.columnId;
    }
    // Snapshot for rollback
    snapshotRef.current = dragColumns;
  }

  function onDragOver({ active, over }: DragOverEvent) {
    if (!over || activeType !== "card") return;

    const activeCardId = active.id as string;
    const overId = over.id as string;
    const overData = over.data.current;

    const fromColumnId = activeCardColumnRef.current;
    if (!fromColumnId) return;

    // Resolve target column
    let toColumnId: string;
    if (overData?.type === "column") {
      toColumnId = overId;
    } else if (overData?.type === "card") {
      toColumnId = overData.columnId;
    } else {
      return;
    }

    if (fromColumnId === toColumnId) {
      setDragColumns((prev) => {
        const col = prev.find((c) => c.id === fromColumnId);
        if (!col) return prev;
        const fromIdx = col.cards.findIndex((c) => c.id === activeCardId);
        const toIdx = col.cards.findIndex((c) => c.id === overId);
        if (fromIdx === -1 || toIdx === -1) return prev;
        return moveCardWithinColumn(prev, fromColumnId, fromIdx, toIdx);
      });
    } else {
      setDragColumns((prev) => {
        const toCol = prev.find((c) => c.id === toColumnId);
        const overIdx = toCol?.cards.findIndex((c) => c.id === overId) ?? -1;
        const insertAt = overIdx >= 0 ? overIdx : undefined;
        return moveCardBetweenColumns(
          prev,
          activeCardId,
          fromColumnId,
          toColumnId,
          insertAt,
        );
      });
      // Track the card's new home column for future onDragOver events
      activeCardColumnRef.current = toColumnId;
    }
  }

  function onDragEnd({ active, over }: DragEndEvent) {
    const currentType = activeType;
    setActiveId(null);
    setActiveType(null);
    activeCardColumnRef.current = null;

    if (!over) {
      // Dropped outside — rollback
      setDragColumns(snapshotRef.current);
      return;
    }

    if (currentType === "column") {
      const fromIdx = snapshotRef.current.findIndex((c) => c.id === active.id);
      const toIdx = snapshotRef.current.findIndex((c) => c.id === over.id);
      if (fromIdx !== -1 && toIdx !== -1 && fromIdx !== toIdx) {
        const next = reorderColumns(
          snapshotRef.current,
          fromIdx,
          toIdx,
        ) as TColumn[];
        setDragColumns(next);
        onColumnsChange?.(next);
        onColumnReorder?.(fromIdx, toIdx);
      } else {
        setDragColumns(snapshotRef.current);
      }
    } else {
      onColumnsChange?.(dragColumns);

      if (onCardMove) {
        const toCol = findCardColumn(dragColumns, active.id as string);
        const fromCol = findCardColumn(
          snapshotRef.current,
          active.id as string,
        );
        const card = findCard(dragColumns, active.id as string);
        if (card && toCol && fromCol) {
          const toIndex = toCol.cards.findIndex((c) => c.id === active.id);
          onCardMove(card as TCard, fromCol.id, toCol.id, toIndex);
        }
      }
    }
  }

  function onDragCancel() {
    setDragColumns(snapshotRef.current);
    setActiveId(null);
    setActiveType(null);
    activeCardColumnRef.current = null;
  }

  const activeCard =
    activeId && activeType === "card"
      ? (findCard(dragColumns, activeId) as TCard | null)
      : null;

  const activeCardColumn = activeCard
    ? (findCardColumn(snapshotRef.current, activeId!) as TColumn | null)
    : null;

  const activeColumnData =
    activeId && activeType === "column"
      ? ((dragColumns.find((c) => c.id === activeId) as TColumn) ?? null)
      : null;

  const MEASURING_CONFIG = {
    droppable: {
      strategy: MeasuringStrategy.Always, // Keeps measurements precise for drop targets
    },
  };

  const value = React.useMemo<KanbanContextValue<TCard, TColumn>>(
    () => ({
      columns: dragColumns,
      activeId,
      activeType,
      activeCard,
      activeCardColumn,
      activeColumnData,
      renderCard,
      renderColumnHeader,
      renderColumnFooter,
      renderEmptyColumn,
    }),
    [
      dragColumns,
      activeId,
      activeType,
      activeCard,
      activeCardColumn,
      activeColumnData,
      renderCard,
      renderColumnHeader,
      renderColumnFooter,
      renderEmptyColumn,
    ],
  );

  return (
    <KanbanCtx.Provider value={value}>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={onDragStart}
        onDragOver={onDragOver}
        onDragEnd={onDragEnd}
        onDragCancel={onDragCancel}
        measuring={MEASURING_CONFIG}
      >
        {children}
      </DndContext>
    </KanbanCtx.Provider>
  );
}

import { KanbanProvider, KanbanProviderProps } from "./kanban-context";
import { KanbanDragOverlay } from "./kanban-drag-overlay";

import type { KanbanCardBase, KanbanColumnBase } from "./types";
import { cn } from "@/lib/utils";

export interface KanbanRootProps extends KanbanProviderProps<
  KanbanCardBase,
  KanbanColumnBase<KanbanCardBase>
> {
  className?: string;
}

/**
 * Kanban — single import that composes the full system.
 *
 * Uses default layout unless you pass children.
 *
 * @example — default layout
 * <KanbanRoot
=  columns={...}
  onColumnsChange={...}
  onCardMove={...}
  renderCard={...}
  renderColumnHeader={...}
  renderColumnFooter={...}
  renderEmptyColumn={...}
 * />
 *
 * @example — custom layout
 * <KanbanRoot>
  *   <MyCustomColumn />
 * </KanbanRoot>
 */
export function KanbanRoot<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard> = KanbanColumnBase<TCard>,
>({ children, className, ...providerProps }: KanbanRootProps) {
  return (
    <KanbanProvider {...providerProps}>
      <div className={cn("flex flex-col", className)}>{children}</div>
      <KanbanDragOverlay />
    </KanbanProvider>
  );
}

KanbanRoot.displayName = "KanbanRoot";

import {
  SortableContext,
  horizontalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useKanban } from "./kanban-context";
import { KanbanColumn } from "./kanban-column";
import { cn } from "@/lib/utils";

export interface KanbanBoardProps {
  className?: string;
}

export function KanbanBoard({ className }: KanbanBoardProps) {
  const { columns } = useKanban();
  const columnIds = columns.map((c) => c.id);

  return (
    <SortableContext items={columnIds} strategy={horizontalListSortingStrategy}>
      <div
        className={cn(
          "flex gap-3 overflow-x-auto pb-4",

          "scrollbar-thin scrollbar-thumb-border scrollbar-track-transparent",
          className,
        )}
      >
        {columns.map((col) => (
          <KanbanColumn key={col.id} column={col} />
        ))}
      </div>
    </SortableContext>
  );
}

KanbanBoard.displayName = "KanbanBoard";

"use client";

import * as React from "react";
import {
  useSortable,
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";
import { useKanban } from "./kanban-context";
import { KanbanCard } from "./kanban-card";
import { cn } from "@/lib/utils";
import type { KanbanCardBase, KanbanColumnBase } from "./types";

export interface KanbanColumnProps<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
> {
  column: TColumn;
  /** Override the default column width */
  width?: number;
  className?: string;
}

export function KanbanColumn<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
>({ column, width = 280, className }: KanbanColumnProps<TCard, TColumn>) {
  const {
    activeId,
    renderColumnHeader,
    renderColumnFooter,
    renderEmptyColumn,
    renderCard,
  } = useKanban<TCard, TColumn>();

  const cardIds = column.cards.map((c) => c.id);

  const {
    attributes,
    listeners,
    setNodeRef: setSortableRef,
    transform,
    transition,
    isDragging: isColumnDragging,
  } = useSortable({
    id: column.id,
    data: { type: "column", column } satisfies {
      type: "column";
      column: TColumn;
    },
  });

  const { setNodeRef: setDroppableRef, isOver } = useDroppable({
    id: column.id,
    data: { type: "column", columnId: column.id },
  });

  // Merge refs — sortable needs ref for position tracking,
  // droppable needs ref for intersection detection
  function mergeRef(el: HTMLDivElement | null) {
    setSortableRef(el);
    setDroppableRef(el);
  }

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    width,
    flexShrink: 0,
  };

  const meta = { cardCount: column.cards.length, isOver };

  return (
    <div
      ref={mergeRef}
      style={style}
      data-column-id={column.id}
      {...attributes}
      className={cn(
        "flex flex-col rounded-xl border border-border bg-background/60",
        "transition-opacity duration-200",
        isColumnDragging && "opacity-40 shadow-2xl",
        isOver && !isColumnDragging && "border-primary/40 bg-primary/5",
        className,
      )}
    >
      {/* ── Column header — drag handle for column reordering ──────────── */}
      <div
        className="flex-shrink-0 cursor-grab active:cursor-grabbing select-none"
        {...listeners}
      >
        {renderColumnHeader ? (
          renderColumnHeader(column, meta)
        ) : (
          <DefaultColumnHeader
            column={column}
            cardCount={column.cards.length}
          />
        )}
      </div>

      {/* ── Card list ──────────────────────────────────────────────────── */}
      <SortableContext items={cardIds} strategy={verticalListSortingStrategy}>
        <div className="flex flex-col gap-2 flex-1 px-3 pb-3 pt-1 min-h-[80px]">
          {column.cards.map((card) => (
            <KanbanCard
              key={card.id}
              card={card}
              column={column}
              renderCard={renderCard}
            />
          ))}

          {/* Empty state — always rendered but visually minimal when non-empty */}
          {column.cards.length === 0 &&
            (renderEmptyColumn ? (
              renderEmptyColumn(column)
            ) : (
              <EmptyDropZone isOver={isOver} />
            ))}
        </div>
      </SortableContext>

      {/* ── Column footer ───────────────────────────────────────────────── */}
      {renderColumnFooter && (
        <div className="flex-shrink-0 px-3 pb-3">
          {renderColumnFooter(column, meta)}
        </div>
      )}
    </div>
  );
}

KanbanColumn.displayName = "KanbanColumn";

function DefaultColumnHeader({
  column,
  cardCount,
}: {
  column: KanbanColumnBase;
  cardCount: number;
}) {
  return (
    <div className="flex items-center justify-between px-3 py-3">
      <span className="text-sm font-semibold text-foreground">
        {column.title}
      </span>
      <span className="text-[10px] font-mono text-muted-foreground/50 bg-muted/50 px-1.5 py-0.5 rounded-full">
        {cardCount}
      </span>
    </div>
  );
}

function EmptyDropZone({ isOver }: { isOver: boolean }) {
  return (
    <div
      className={cn(
        "flex-1 min-h-[80px] rounded-lg border border-dashed transition-colors",
        isOver
          ? "border-primary/50 bg-primary/5"
          : "border-border/40 bg-transparent",
      )}
    />
  );
}

import * as React from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "@/lib/utils";
import type { KanbanCardBase, KanbanColumnBase, CardRenderMeta } from "./types";

export interface KanbanCardProps<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
> {
  card: TCard;
  column: TColumn;
  renderCard: (
    card: TCard,
    column: TColumn,
    meta: CardRenderMeta,
  ) => React.ReactNode;
  className?: string;
}

export const KanbanCard = React.memo(function KanbanCard<
  TCard extends KanbanCardBase,
  TColumn extends KanbanColumnBase<TCard>,
>({ card, column, renderCard, className }: KanbanCardProps<TCard, TColumn>) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: card.id,
    data: {
      type: "card",
      card,
      column,
      columnId: column.id,
    },
  });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,

    willChange: transform ? "transform" : undefined,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className={cn(
        "touch-none select-none cursor-grab active:cursor-grabbing",
        isDragging && "opacity-30",
        className,
      )}
    >
      {renderCard(card, column, { isDragging, isOverlay: false })}
    </div>
  );
}) as <TCard extends KanbanCardBase, TColumn extends KanbanColumnBase<TCard>>(
  props: KanbanCardProps<TCard, TColumn>,
) => React.JSX.Element;

(KanbanCard as any).displayName = "KanbanCard";

import { DragOverlay, defaultDropAnimationSideEffects } from "@dnd-kit/core";
import { useKanban } from "./kanban-context";
import { cn } from "@/lib/utils";

const DROP_ANIMATION = {
  duration: 180,
  easing: "cubic-bezier(0.18, 0.67, 0.6, 1.22)",
  sideEffects: defaultDropAnimationSideEffects({
    styles: { active: { opacity: "0.4" } },
  }),
};

export function KanbanDragOverlay() {
  const {
    activeId,
    activeType,
    activeCard,
    activeCardColumn,
    activeColumnData,
    renderCard,
    renderColumnHeader,
  } = useKanban();

  return (
    <DragOverlay dropAnimation={DROP_ANIMATION}>
      {activeType === "card" && activeCard && activeCardColumn && (
        <div className="rotate-[1.5deg] scale-[1.02] shadow-2xl">
          {renderCard(activeCard, activeCardColumn, {
            isDragging: false,
            isOverlay: true,
          })}
        </div>
      )}

      {activeType === "column" && activeColumnData && (
        <div
          className={cn(
            "rotate-[1deg] scale-[1.01] shadow-2xl opacity-95",
            "border border-border bg-card/90 rounded-xl",
          )}
          style={{ width: 280 }}
        >
          {renderColumnHeader ? (
            renderColumnHeader(activeColumnData, {
              cardCount: activeColumnData.cards.length,
              isOver: false,
            })
          ) : (
            <div className="flex items-center justify-between px-3 py-3">
              <span className="text-sm font-semibold">
                {activeColumnData.title}
              </span>
              <span className="text-[10px] font-mono text-muted-foreground/50 bg-muted/50 px-1.5 py-0.5 rounded-full">
                {activeColumnData.cards.length}
              </span>
            </div>
          )}
        </div>
      )}
    </DragOverlay>
  );
}

KanbanDragOverlay.displayName = "KanbanDragOverlay";

export { KanbanRoot } from "./kanban-root";
export { KanbanBoard } from "./kanban-board";
export { KanbanColumn } from "./kanban-column";
export { KanbanCard } from "./kanban-card";
export { KanbanDragOverlay } from "./kanban-drag-overlay";
export { KanbanProvider, useKanban } from "./kanban-context";

export type {
  KanbanCardBase,
  KanbanColumnBase,
  CardRenderMeta,
  ColumnRenderMeta,
  KanbanContextValue,
} from "./types";
